insert into public.pages (id, handle, title, status, seo_title, seo_description) values
  ('5c775344-a669-4ec3-aa1f-58aca6321370', 'home', 'Nature Nesto', 'published', 'Nature Nesto | Plants, Pots and Plant Styling in Lahore', 'Bring life to your space with Nature Nesto, a Lahore plant and decor studio. Indoor and outdoor plants, pots and planters, and personalised plant styling.')
insert into public.page_sections (id, page_id, type, position, data, status) values
  ('6ef9b9a0-bc73-4666-ade8-50e9b4dec4ab', '5c775344-a669-4ec3-aa1f-58aca6321370', 'hero', 0, '{"headline":"Bring Life to Your Space","subline":"Welcome to Nature Nesto","secondary":"Transform Your Space with Us","cta":{"label":"Shop Now","href":"/pots-and-planters","flag":"Shop destination to confirm. No online shop in scope yet."},"poster":{"src":"https://images.unsplash.com/photo-1741265828633-ed8d0bd12f09?auto=format&fit=crop&w=1600&q=75","flag":"Stand-in photograph. Replace with a frame from the final hero video."},"video":{"src":"https://videos.pexels.com/video-files/3770017/3770017-hd_1920_1080_25fps.mp4","flag":"Inferred from an earlier fetch. Confirm usage rights and poster frame."}}'::jsonb, 'published'),
  ('eb03c87e-4b30-4a57-a3c3-4625d0f898e1', '5c775344-a669-4ec3-aa1f-58aca6321370', 'tagline', 1, '{"items":[{"text":"One Plant","icon":"plant"},{"text":"One Piece","icon":"vase"},{"text":"One Vibe at a time.","icon":"table"}]}'::jsonb, 'published'),
  ('6aefdbd2-2664-4beb-a4aa-87e512e9a262', '5c775344-a669-4ec3-aa1f-58aca6321370', 'value_props', 2, '{"items":[{"title":"Expert Guidance","body":"Success starts with choosing the right plants. We''ll make sure you do.","icon":"guidance"},{"title":"Connect & Grow","body":"Community is everything. Our workshops and events help you learn and connect.","icon":"community"},{"title":"Judgement-Free Service","body":"Our dedicated team is always available to assist — no question too small or too silly!","icon":"support"}]}'::jsonb, 'published'),
  ('1295c7fb-a7b9-4614-a559-ffa7f54b03f9', '5c775344-a669-4ec3-aa1f-58aca6321370', 'how_it_works', 3, '{"eyebrow":"HOW NATURE NESTO WORKS","title":"How Nature Nesto Works","steps":[{"number":"01","title":"Share Your Space","body":"Whether it’s your home, office, café, or any other area — share a few details and images with us. Let us know your space dimensions, vibe, lighting, and any inspirations or mood boards you love.","flag":"Step 01 title is a placeholder. Not present in the pasted copy."},{"number":"02","title":"Get a Personalized Plan","body":"Our team of plant stylists and designers will curate a tailored concept just for you — including recommended indoor/outdoor plants, decorative pieces, custom artwork or posters, and layout ideas to bring it all together."},{"number":"03","title":"Choose What You Love","body":"From the curated plan, select the items and services you love most — plants, pots, artwork, or full styling. Need something custom? No worries, we’ve got you covered."},{"number":"04","title":"We Deliver & Style It","body":"Once you confirm, we prepare everything with care and deliver it to your doorstep. If you opt for our styling services, we’ll help set everything up — from plant placement to art installation."},{"number":"05","title":"Ongoing Plant Care","body":"For businesses and busy clients, we also offer ongoing plant maintenance services to keep everything fresh, vibrant, and healthy all year round."}]}'::jsonb, 'published'),
  ('f8f95835-bfcd-47f6-a79b-91199de615d0', '5c775344-a669-4ec3-aa1f-58aca6321370', 'services', 4, '{"eyebrow":"NATURE NESTO SERVICES","services":[{"slug":"space-planning","icon":"floorplan","featured":true,"title":"Space Planning & Decor Consultation","href":"/services/space-planning","legacyPath":"/premium-outdoor-plants-services-space-planning-and-decor-consultation"},{"slug":"plant-styling","icon":"leaf","title":"Indoor & Outdoor Plants Styling","href":"/services/plant-styling","legacyPath":"/premium-indoor-plants-services-indoor-and-outdoor-plants-styling"},{"slug":"custom-posters","icon":"poster","title":"Custom Poster & Quote Design","href":"/services/custom-posters","legacyPath":"/services-custom-poster-and-quote-design"},{"slug":"gift-bundles","icon":"gift","title":"Personalized Gift Bundles","href":"/services/gift-bundles","legacyPath":"/services-personalized-gift-bundles"},{"slug":"pot-customization","icon":"pot","title":"Pot & Decor Customization","href":"/services/pot-customization","legacyPath":"/services-pot-and-decor-customization"},{"slug":"corporate-styling","icon":"building","title":"Corporate & Commercial Styling","href":"/services/corporate-styling","legacyPath":"/premium-plants-services-corporate-and-commercial-styling"}]}'::jsonb, 'published'),
  ('15655181-b943-48f1-adef-bb625a7c9914', '5c775344-a669-4ec3-aa1f-58aca6321370', 'banner', 5, '{"headline":"Predict the future by creating it","secondary":"Transform Your Space with Us","cta":{"label":"Shop Now","href":"/pots-and-planters","flag":"Shop destination to confirm. No online shop in scope yet."},"image":{"src":"https://images.unsplash.com/photo-1684662863663-d25e39fc4c10?auto=format&fit=crop&w=1600&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}}'::jsonb, 'published'),
  ('c05711a4-abcb-4553-a06a-bdfc396d05d3', '5c775344-a669-4ec3-aa1f-58aca6321370', 'plants', 6, '{"title":"Plants For Everyone","categories":[{"slug":"indoor-plants","title":"Indoor Plants","href":"/indoor-plants","image":{"src":"https://images.unsplash.com/photo-1610470886268-29cce96d155d?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"outdoor-plants","title":"Outdoor Plants","href":"/outdoor-plants","image":{"src":"https://images.unsplash.com/photo-1750083785560-51be2aa7080d?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"pet-friendly","title":"Pet Friendly Plants","href":"/plants/pet-friendly","image":{"src":"https://images.unsplash.com/photo-1696339566578-69707197b0b0?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"easy-care","title":"Easy Care Plants","href":"/plants/easy-care","image":{"src":"https://images.unsplash.com/photo-1599719840163-1cd5b7c1fabe?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"orchids","title":"Orchids","href":"/plants/orchids","image":{"src":"https://images.unsplash.com/photo-1577378978713-9bebf3db8312?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"large-plants","title":"Large Plants","href":"/plants/large-plants","image":{"src":"https://images.unsplash.com/photo-1599008634401-92a2827a9a72?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"low-light","title":"Low Light Tolerate Plants","href":"/plants/low-light","image":{"src":"https://images.unsplash.com/photo-1614594895304-fe7116ac3b58?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}},{"slug":"plant-care","title":"Plants Care","href":"/plants/plant-care","image":{"src":"https://images.unsplash.com/photo-1773332611574-d73d8f5cea36?auto=format&fit=crop&w=900&q=75","alt":"","flag":"Stand-in photograph. Replace with the studio''s own."}}]}'::jsonb, 'published'),
  ('f3e6265d-70a0-445c-ac27-147a64a43fc6', '5c775344-a669-4ec3-aa1f-58aca6321370', 'need_help', 7, '{"title":"Need Help?","body":"Your confidence is our priority. Unsure what plants will work with your light? New to gardening outdoors and need some advice? Reach out, we''re here to help.","signOff":"SPEAK TO TEAM NATURE NESTO","channels":[{"kind":"whatsapp","label":"Chat/ WhatsApp","prompt":"DM to expert","display":"+92 318 0427 602","href":"https://wa.me/923180427602","flag":"Pasted copy does not say which number is WhatsApp and which is Call. Mapping is a guess."},{"kind":"call","label":"Call","prompt":"Speak to expert","display":"+92 322 4024 862","href":"tel:+923224024862","flag":"Pasted copy does not say which number is WhatsApp and which is Call. Mapping is a guess."},{"kind":"email","label":"Email","prompt":"Send a note to","display":"info@naturenesto.com","href":"mailto:info@naturenesto.com"}]}'::jsonb, 'published')
