insert into public.products (id, handle, title, status, vendor, product_type, tags, description, short_description, specs, included, care) values
  ('2ce4c822-02db-448a-a292-d485c1da336e', 'monstera', 'Monstera Deliciosa', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'large-plants', 'badge:bestseller']::text[], '{"format":"markdown","source":"The monstera is the classic statement plant. Its glossy leaves split and perforate as it matures, and it grows quickly in bright, indirect light.\n\nGive it a moss pole or a sturdy stake as it climbs, and wipe the leaves now and then so they stay glossy."}'::jsonb, 'Big split leaves that make any corner look styled.', '[{"label":"Size","value":"Medium, 90 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"toxic","level":"easy","size":"Medium, 90 cm"}'::jsonb),
  ('311100a8-4ae2-44fb-af2b-1eb229e9d4a3', 'snake-plant', 'Snake Plant', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'easy-care', 'low-light', 'badge:easy-care', 'badge:low-light']::text[], '{"format":"markdown","source":"Snake plants cope with dim rooms, dry spells and a forgetful owner. Their upright, sword shaped leaves suit hallways, bedrooms and office desks.\n\nWater only when the soil has dried out completely, and less in winter."}'::jsonb, 'Upright, tough and nearly unkillable.', '[{"label":"Size","value":"Small, 45 cm"},{"label":"Light","value":"Low light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"low","water":"low","pet":"toxic","level":"easy","size":"Small, 45 cm"}'::jsonb),
  ('a05929d7-5509-4451-a6e2-f8edb4e6d72b', 'zz-plant', 'ZZ Plant', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'easy-care', 'low-light', 'badge:low-light']::text[], '{"format":"markdown","source":"The ZZ plant stores water in its thick rhizomes, so it forgives missed waterings and thrives away from windows. A good first plant for offices and shaded rooms.\n\nLet the soil dry between drinks and keep it out of harsh afternoon sun."}'::jsonb, 'Glossy, patient and happy in low light.', '[{"label":"Size","value":"Small, 50 cm"},{"label":"Light","value":"Low light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"low","water":"low","pet":"toxic","level":"easy","size":"Small, 50 cm"}'::jsonb),
  ('c314d750-e2a4-49bc-a69a-5d259006049a', 'golden-pothos', 'Golden Pothos', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'easy-care', 'low-light', 'badge:easy-care']::text[], '{"format":"markdown","source":"Pothos is one of the easiest trailing plants. It tolerates low light, tells you when it is thirsty by drooping slightly, and perks up quickly after watering.\n\nTrim the vines to keep it full, and root the cuttings in water to make more."}'::jsonb, 'Trailing vines for shelves, hooks and high cabinets.', '[{"label":"Size","value":"Hanging, 30 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"toxic","level":"easy","size":"Hanging, 30 cm"}'::jsonb),
  ('79f62119-ad67-4c97-a486-a3bd86d3d62b', 'peace-lily', 'Peace Lily', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'low-light']::text[], '{"format":"markdown","source":"Peace lilies bring white spathes and deep green foliage to rooms that do not get much sun. They tell you plainly when they are thirsty, which makes them easy to read.\n\nKeep the soil lightly moist and the plant out of direct sun."}'::jsonb, 'Dark leaves and white blooms, even in shade.', '[{"label":"Size","value":"Medium, 60 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"toxic","level":"easy","size":"Medium, 60 cm"}'::jsonb),
  ('d8cd806b-39a8-4c23-a2a8-1a243734f815', 'fiddle-leaf-fig', 'Fiddle Leaf Fig', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'large-plants', 'badge:new']::text[], '{"format":"markdown","source":"Large, violin shaped leaves make the fiddle leaf fig a favourite for living rooms. It likes bright light and a steady routine, so pick a spot and leave it there.\n\nTurn the pot a quarter every few weeks so it grows evenly."}'::jsonb, 'A tall, sculptural plant for a bright corner.', '[{"label":"Size","value":"Large, 150 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","pet":"toxic","level":"moderate","size":"Large, 150 cm"}'::jsonb),
  ('7697ef74-6969-4d59-a0fc-d509b918d3be', 'calathea', 'Calathea Orbifolia', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'pet-friendly', 'low-light', 'badge:pet-safe']::text[], '{"format":"markdown","source":"Calatheas are grown for their striped, patterned foliage, and their leaves move through the day. They like humidity and even moisture, and they are safe around pets.\n\nUse filtered water where you can, and keep the plant away from drafts."}'::jsonb, 'Patterned leaves that fold up at night.', '[{"label":"Size","value":"Medium, 55 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Keep the soil lightly moist"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"frequent","pet":"safe","level":"moderate","size":"Medium, 55 cm"}'::jsonb),
  ('ce5dfd39-9069-4f7f-a1b3-356036aea4e5', 'spider-plant', 'Spider Plant', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'pet-friendly', 'easy-care', 'badge:pet-safe', 'badge:easy-care']::text[], '{"format":"markdown","source":"Spider plants are cheerful, forgiving and safe around cats and dogs. They send out little plantlets on long stems that you can pot up and give away.\n\nBright, indirect light keeps the stripes sharp."}'::jsonb, 'Arching striped leaves and baby plants to share.', '[{"label":"Size","value":"Small, 30 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"safe","level":"easy","size":"Small, 30 cm"}'::jsonb),
  ('b0173f22-5663-4d44-abfe-d11bc18e7df5', 'boston-fern', 'Boston Fern', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'pet-friendly', 'badge:pet-safe']::text[], '{"format":"markdown","source":"Boston ferns fill a hanging pot with lush fronds and are safe for pets. They enjoy humidity, so a bathroom or a spot away from the air conditioner suits them.\n\nKeep the soil evenly moist and never let it dry out fully."}'::jsonb, 'Soft, feathery fronds for a hanging basket.', '[{"label":"Size","value":"Hanging, 40 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Keep the soil lightly moist"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"frequent","pet":"safe","level":"moderate","size":"Hanging, 40 cm"}'::jsonb),
  ('6403312b-6874-4b71-a4d7-d2b7102fca91', 'areca-palm', 'Areca Palm', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'large-plants', 'pet-friendly', 'badge:pet-safe']::text[], '{"format":"markdown","source":"The areca palm brings a light, tropical look to living rooms and lobbies, and it is safe around pets. It likes bright, indirect light and regular watering.\n\nAvoid moving it often, as palms prefer a settled spot."}'::jsonb, 'A full, feathery palm that softens a room.', '[{"label":"Size","value":"Large, 160 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","pet":"safe","level":"easy","size":"Large, 160 cm"}'::jsonb),
  ('1a33a491-889d-473c-ab03-0de51d8b2964', 'rubber-plant', 'Rubber Plant', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'large-plants']::text[], '{"format":"markdown","source":"Rubber plants are bold and easy, with thick leaves that hold their shine. They grow steadily upward in bright light and need little fuss.\n\nDust the leaves with a damp cloth to keep them glossy."}'::jsonb, 'Thick, glossy leaves on a strong upright stem.', '[{"label":"Size","value":"Medium, 80 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","pet":"toxic","level":"easy","size":"Medium, 80 cm"}'::jsonb),
  ('4069e142-cdf9-4485-a90e-c4c7e0773c03', 'chinese-money-plant', 'Chinese Money Plant', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'pet-friendly', 'easy-care', 'badge:pet-safe', 'badge:new']::text[], '{"format":"markdown","source":"Pilea peperomioides is loved for its round leaves and tidy shape. It is safe for pets and easy to multiply, since it sends up baby plants around the base.\n\nTurn it regularly so it grows evenly towards the light."}'::jsonb, 'Round, coin shaped leaves on a compact plant.', '[{"label":"Size","value":"Small, 30 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"safe","level":"easy","size":"Small, 30 cm"}'::jsonb),
  ('8a443bf5-88f2-46f9-ab0e-7da8ee10255f', 'heartleaf-philodendron', 'Heartleaf Philodendron', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'easy-care', 'low-light']::text[], '{"format":"markdown","source":"A relaxed, fast growing vine with soft, heart shaped leaves. Let it trail from a shelf or climb a small stake, and it will adapt to most indoor spots.\n\nWater when the top of the soil feels dry."}'::jsonb, 'Heart shaped leaves that trail or climb.', '[{"label":"Size","value":"Small, 25 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"toxic","level":"easy","size":"Small, 25 cm"}'::jsonb),
  ('b2028998-fd75-46d5-a215-be0953442daf', 'hoya-trio', 'Hoya Trio', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants', 'easy-care']::text[], '{"format":"markdown","source":"Hoyas have thick, waxy leaves and store water well, so they suit a bright windowsill and a relaxed watering routine. This set of three works well along a shelf or table.\n\nWater only once the soil has dried through."}'::jsonb, 'Three waxy hoyas, ready to display together.', '[{"label":"Size","value":"Three plants"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Three live plants in nursery pots', 'Care guidance for your plants']::text[], '{"light":"bright","water":"low","pet":"safe","level":"easy","size":"Three plants"}'::jsonb),
  ('e2814249-9778-4443-a8ca-84be36add3d1', 'anthurium', 'Anthurium', 'draft', 'Nature Nesto', 'Plant', array['indoor-plants']::text[], '{"format":"markdown","source":"Anthuriums flower on and off through the year, with waxy red spathes above dark green leaves. They like bright, indirect light and a bit of humidity.\n\nKeep the plant away from pets, as the leaves can irritate if chewed."}'::jsonb, 'Glossy red blooms that last for weeks.', '[{"label":"Size","value":"Small, 35 cm"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"moderate","pet":"toxic","level":"moderate","size":"Small, 35 cm"}'::jsonb),
  ('b3f5ebd6-dfe9-4abb-aa98-e5b6811d4406', 'phalaenopsis-white', 'White Phalaenopsis Orchid', 'draft', 'Nature Nesto', 'Plant', array['orchids', 'pet-friendly', 'indoor-plants', 'badge:pet-safe', 'badge:bestseller']::text[], '{"format":"markdown","source":"The moth orchid is the easiest orchid to keep at home. The flowers can last for months, and the plant often blooms again with a little patience.\n\nWater once the roots turn silvery, and give it bright light without direct sun."}'::jsonb, 'Elegant white blooms on a double stem.', '[{"label":"Size","value":"Double stem"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"low","pet":"safe","level":"moderate","size":"Double stem"}'::jsonb),
  ('ec0c44a7-ae85-4976-ac0d-103d65209a3d', 'phalaenopsis-blush', 'Blush Phalaenopsis Orchid', 'draft', 'Nature Nesto', 'Plant', array['orchids', 'pet-friendly', 'badge:pet-safe']::text[], '{"format":"markdown","source":"A blush toned moth orchid with long lasting flowers, safe around pets. It sits well on a table or sideboard in bright, indirect light.\n\nWater lightly and let the roots dry between drinks."}'::jsonb, 'Soft pink and white blooms, a lovely gift.', '[{"label":"Size","value":"Double stem"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"medium","water":"low","pet":"safe","level":"moderate","size":"Double stem"}'::jsonb),
  ('cbfcaefd-e3e0-426f-aaf9-82a66fcd9adb', 'dendrobium', 'Dendrobium Orchid', 'draft', 'Nature Nesto', 'Plant', array['orchids', 'badge:new']::text[], '{"format":"markdown","source":"Dendrobiums carry clusters of flowers along tall canes. They enjoy bright light and a little less water in the cooler months.\n\nFeed lightly during growth for the best flowering."}'::jsonb, 'Upright canes covered in small blooms.', '[{"label":"Size","value":"Single stem"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"low","pet":"safe","level":"moderate","size":"Single stem"}'::jsonb),
  ('84fac122-deda-4bc6-a12c-181214c61036', 'orchid-trio', 'Orchid Trio in Ceramic Bowl', 'draft', 'Nature Nesto', 'Plant', array['orchids']::text[], '{"format":"markdown","source":"A gift ready arrangement of three moth orchids planted together in a glazed ceramic bowl. It makes a centrepiece for a dining table or a reception desk.\n\nKeep it in bright, indirect light and water lightly."}'::jsonb, 'Three orchids arranged in one glazed bowl.', '[{"label":"Size","value":"Three plants"},{"label":"Light","value":"Medium, indirect light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Safe for pets"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Three orchids planted in a ceramic bowl', 'Care guidance for your orchids']::text[], '{"light":"medium","water":"low","pet":"safe","level":"moderate","size":"Three plants"}'::jsonb),
  ('2ebfa05a-2dc0-423c-a91f-8d16abdf0a87', 'bougainvillea', 'Bougainvillea', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'badge:bestseller']::text[], '{"format":"markdown","source":"Bougainvillea loves full sun and heat, and rewards a sunny balcony or boundary wall with months of bright bracts. It flowers best when kept a little dry.\n\nPrune after a flush of flowers to keep it shapely."}'::jsonb, 'Papery pink bracts that colour a whole wall.', '[{"label":"Size","value":"Medium, 70 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","level":"easy","size":"Medium, 70 cm"}'::jsonb),
  ('5895e3fb-5a98-46a7-ad1f-a29941b3ed6a', 'motia-jasmine', 'Motia Jasmine', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants']::text[], '{"format":"markdown","source":"Motia, or Arabian jasmine, is loved across Pakistan for its fragrant white flowers. It prefers sunshine and regular water, and does well in a large pot.\n\nPick the flowers regularly to encourage more."}'::jsonb, 'Small white flowers with an evening fragrance.', '[{"label":"Size","value":"Small, 40 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","level":"easy","size":"Small, 40 cm"}'::jsonb),
  ('04387484-b58b-4900-ae26-72acf0558a52', 'hibiscus', 'Hibiscus', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants']::text[], '{"format":"markdown","source":"Hibiscus produces large, colourful flowers in warm weather. It needs sun, regular watering and an occasional feed to keep blooming.\n\nPinch back tips in spring for a bushier plant."}'::jsonb, 'Big, bold blooms for a sunny spot.', '[{"label":"Size","value":"Medium, 60 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Keep the soil lightly moist"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"frequent","level":"moderate","size":"Medium, 60 cm"}'::jsonb),
  ('9c561f5c-2b95-48ca-aa88-b8037e3ca95b', 'olive-tree', 'Olive Tree', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'large-plants', 'badge:new']::text[], '{"format":"markdown","source":"An olive tree gives patios and terraces a calm, Mediterranean look. It wants full sun, good drainage and not too much water.\n\nUse a large pot with drainage holes and refresh the top soil each year."}'::jsonb, 'Silver green leaves and a sculptural trunk.', '[{"label":"Size","value":"Large, 140 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"low","level":"easy","size":"Large, 140 cm"}'::jsonb),
  ('b0fd2950-3ff0-4867-a1b5-04ba7f1d5372', 'aloe-vera', 'Aloe Vera', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'easy-care', 'badge:easy-care']::text[], '{"format":"markdown","source":"Aloe vera thrives in bright light and needs very little water. Its thick leaves store moisture, so let the soil dry out well between waterings.\n\nA sunny window or balcony suits it best."}'::jsonb, 'A useful, sun loving succulent.', '[{"label":"Size","value":"Small, 25 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"low","pet":"toxic","level":"easy","size":"Small, 25 cm"}'::jsonb),
  ('1d4e42dd-f3da-490c-afe6-d9f6bc1ac274', 'jade-plant', 'Jade Plant', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'easy-care']::text[], '{"format":"markdown","source":"The jade plant is a long lived succulent that slowly becomes a small tree. It needs bright light and sparing water.\n\nAvoid overwatering, which is the one thing it dislikes."}'::jsonb, 'Thick leaves on a woody, tree like stem.', '[{"label":"Size","value":"Small, 30 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Pets","value":"Keep away from pets"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"low","pet":"toxic","level":"easy","size":"Small, 30 cm"}'::jsonb),
  ('ac6f5fa6-91c1-40bd-a040-0c783830fddd', 'bird-of-paradise', 'Bird of Paradise', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'large-plants']::text[], '{"format":"markdown","source":"A showy plant with big banana like leaves and, with enough sun, striking orange and blue flowers. It suits bright patios and sunny, spacious rooms.\n\nWater regularly and give it room to grow."}'::jsonb, 'Tall, paddle shaped leaves and tropical flowers.', '[{"label":"Size","value":"Large, 130 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Care level","value":"Moderate"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"moderate","level":"moderate","size":"Large, 130 cm"}'::jsonb),
  ('53b44df3-4750-447d-afce-577432770620', 'lavender', 'Lavender', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants']::text[], '{"format":"markdown","source":"Lavender loves sun and sharp drainage. Plant it in a terracotta pot on a bright balcony and trim after flowering to keep it compact.\n\nIt prefers to stay on the dry side."}'::jsonb, 'Fragrant purple spikes for a sunny corner.', '[{"label":"Size","value":"Small, 30 cm"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Live plant in its nursery pot', 'Care guidance for your plant']::text[], '{"light":"bright","water":"low","level":"easy","size":"Small, 30 cm"}'::jsonb),
  ('946546bf-d0c5-4b9c-a016-0a7fa89987f3', 'herb-duo', 'Basil & Rosemary Duo', 'draft', 'Nature Nesto', 'Plant', array['outdoor-plants', 'easy-care']::text[], '{"format":"markdown","source":"A pair of potted herbs for the kitchen. Basil likes regular water and warmth, while rosemary prefers to dry out between drinks, so give each its own pot.\n\nHarvest often from the top to keep them bushy."}'::jsonb, 'Two kitchen herbs, ready for a sunny windowsill.', '[{"label":"Size","value":"Two herbs"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Water when the top soil is dry"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Two live herbs in nursery pots', 'Care guidance for your herbs']::text[], '{"light":"bright","water":"moderate","level":"easy","size":"Two herbs"}'::jsonb),
  ('7c9b3d90-048d-4688-acaf-b07ed1adf5bb', 'cactus-collection', 'Cactus Collection', 'draft', 'Nature Nesto', 'Plant', array['easy-care', 'indoor-plants', 'badge:easy-care']::text[], '{"format":"markdown","source":"Five small cacti in different shapes and colours, grown in nursery pots. They like as much sun as you can give them and very little water.\n\nPlace them on a bright windowsill and water only when fully dry."}'::jsonb, 'A mixed set of small potted cacti.', '[{"label":"Size","value":"Set of five"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Five small cacti in nursery pots', 'Care guidance for your cacti']::text[], '{"light":"bright","water":"low","level":"easy","size":"Set of five"}'::jsonb),
  ('a4206d26-7032-4ae1-a54a-67c2056b576d', 'succulent-table-set', 'Succulent Table Set', 'draft', 'Nature Nesto', 'Plant', array['easy-care', 'indoor-plants']::text[], '{"format":"markdown","source":"A set of four small succulents in individual pots, sized for a desk, shelf or coffee table. They like bright light and a very light hand with water.\n\nTurn them now and then so they keep an even shape."}'::jsonb, 'Small succulents for a desk or coffee table.', '[{"label":"Size","value":"Set of four"},{"label":"Light","value":"Bright light"},{"label":"Watering","value":"Let the soil dry between waterings"},{"label":"Care level","value":"Easy"}]'::jsonb, array['Four small succulents in pots', 'Care guidance for your succulents']::text[], '{"light":"bright","water":"low","level":"easy","size":"Set of four"}'::jsonb),
  ('0c8e0518-45b1-46b9-aabf-82245fc558c9', 'ceramic-bowl', 'Glazed Ceramic Bowl', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters', 'badge:bestseller']::text[], '{"format":"markdown","source":"A wide, shallow glazed bowl that suits orchids, succulents and low arrangements. Add a layer of drainage stones, or use it as a cover for a nursery pot."}'::jsonb, 'A wide glazed bowl for orchids and arrangements.', '[{"label":"Size","value":"30 cm"},{"label":"Material","value":"Glazed ceramic"}]'::jsonb, array['One planter, as shown', 'Packed to protect the finish']::text[], '{"size":"30 cm"}'::jsonb),
  ('712cf79b-2349-4537-ab8c-6d84e8ad45f5', 'terracotta-classic', 'Classic Terracotta Pot', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters']::text[], '{"format":"markdown","source":"Terracotta is porous, so soil dries evenly and roots stay healthy, which makes it a good choice for succulents, herbs and anything that dislikes wet feet."}'::jsonb, 'The everyday clay pot that lets roots breathe.', '[{"label":"Size","value":"25 cm"},{"label":"Material","value":"Terracotta clay"}]'::jsonb, array['One planter, as shown', 'Packed to protect the finish']::text[], '{"size":"25 cm"}'::jsonb),
  ('3af9b99a-28f7-4895-a1bc-0164297e6fb8', 'charcoal-cylinder', 'Charcoal Cylinder Planter', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters', 'badge:new']::text[], '{"format":"markdown","source":"A tall cylinder planter in a deep charcoal finish that makes green leaves stand out. It suits snake plants, rubber plants and palms in modern rooms."}'::jsonb, 'A deep charcoal planter with clean lines.', '[{"label":"Size","value":"35 cm"},{"label":"Finish","value":"Charcoal"}]'::jsonb, array['One planter, as shown', 'Packed to protect the finish']::text[], '{"size":"35 cm"}'::jsonb),
  ('4bb9db70-09c2-44d0-a983-be5e0c99a1f3', 'tall-floor-planter', 'Tall Floor Planter', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters', 'large-plants']::text[], '{"format":"markdown","source":"A tall floor standing planter with room for large plants such as fiddle leaf figs and palms. Place it near a window and fill with a well draining mix."}'::jsonb, 'A tall planter for large plants and bright corners.', '[{"label":"Size","value":"70 cm"}]'::jsonb, array['One planter, as shown', 'Packed to protect the finish']::text[], '{"size":"70 cm"}'::jsonb),
  ('0ebcd242-b385-44da-a520-4ea5b4194936', 'terracotta-set', 'Terracotta Trio Set', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters']::text[], '{"format":"markdown","source":"Three terracotta pots in graduated sizes, ideal for grouping on a shelf, step or windowsill. Pair them with herbs and succulents."}'::jsonb, 'Three nesting clay pots in graduated sizes.', '[{"label":"Size","value":"15, 20 and 25 cm"},{"label":"Material","value":"Terracotta clay"}]'::jsonb, array['Three terracotta pots', 'Packed to protect the finish']::text[], '{"size":"15, 20 and 25 cm"}'::jsonb),
  ('a7523c75-ba46-4b84-a656-d00aa220c041', 'ceramic-planter-white', 'Matte White Planter', 'draft', 'Nature Nesto', 'Pot & planter', array['pots-and-planters']::text[], '{"format":"markdown","source":"A matte white ceramic planter with a quiet finish that suits any room. It pairs well with leafy plants such as pilea, pothos and ferns."}'::jsonb, 'A soft matte white planter that goes with everything.', '[{"label":"Size","value":"28 cm"},{"label":"Finish","value":"Matte white ceramic"}]'::jsonb, array['One planter, as shown', 'Packed to protect the finish']::text[], '{"size":"28 cm"}'::jsonb),
  ('af827d02-cbd2-4b30-adc9-7ff5262b708c', 'potting-mix', 'Premium Potting Mix', 'draft', 'Nature Nesto', 'Plant care', array['plant-care', 'badge:bestseller']::text[], '{"format":"markdown","source":"A ready to use potting mix for indoor and balcony plants. It holds enough moisture to feed roots while draining freely, which helps prevent soggy soil."}'::jsonb, 'A light, well draining mix for houseplants.', '[{"label":"Size","value":"5 kg"}]'::jsonb, array['One 5 kg bag of potting mix']::text[], '{"size":"5 kg"}'::jsonb),
  ('fc1216d9-739e-45bc-ad03-eaaf0b84bb60', 'neem-spray', 'Neem Oil Leaf Spray', 'draft', 'Nature Nesto', 'Plant care', array['plant-care']::text[], '{"format":"markdown","source":"A ready to use neem oil spray for keeping leaves clean and discouraging common pests. Test on one leaf first and apply away from strong midday sun."}'::jsonb, 'A gentle spray for leaf care and pest control.', '[{"label":"Size","value":"500 ml"}]'::jsonb, array['One 500 ml spray bottle']::text[], '{"size":"500 ml"}'::jsonb),
  ('fc964e89-db07-4625-ad8f-9345b3199f21', 'watering-can', 'Brass Spout Watering Can', 'draft', 'Nature Nesto', 'Plant care', array['plant-care', 'badge:new']::text[], '{"format":"markdown","source":"A small watering can with a long spout for reaching under leaves and into crowded pots. It holds enough for a shelf of plants without being heavy."}'::jsonb, 'A slim spouted can for precise watering.', '[{"label":"Size","value":"1.5 L"}]'::jsonb, array['One watering can']::text[], '{"size":"1.5 L"}'::jsonb),
  ('67f266c7-00a8-4807-aeba-b22f8dc5af93', 'pruning-shears', 'Pruning Shears', 'draft', 'Nature Nesto', 'Plant care', array['plant-care']::text[], '{"format":"markdown","source":"Hand shears for trimming stems, removing spent flowers and shaping bushes. Clean the blades between plants to avoid passing on disease."}'::jsonb, 'Sharp shears for tidy cuts and healthy growth.', '[{"label":"Size","value":"20 cm"}]'::jsonb, array['One pair of pruning shears']::text[], '{"size":"20 cm"}'::jsonb),
  ('cf781e66-986d-4bdd-a382-a710357239e6', 'organic-feed', 'Organic Plant Feed', 'draft', 'Nature Nesto', 'Plant care', array['plant-care', 'easy-care']::text[], '{"format":"markdown","source":"An organic feed to mix into the top soil during the growing season. Follow the instructions on the pack, and feed less in winter when plants grow slowly."}'::jsonb, 'A gentle feed for leafy plants and flowers.', '[{"label":"Size","value":"1 kg"}]'::jsonb, array['One 1 kg pack of plant feed']::text[], '{"size":"1 kg"}'::jsonb)
